  internal void ResetRespawnLoadout(R24PlayableMatchRules rules)
  {
   ResetLanLoadoutInput(false);
   if(!Gameplay.ConfigureLocalMatchLoadout(rules.StartingCatalog))throw new InvalidOperationException("Respawn loadout refused");
   var reserves=Networking.R24LanLoadout.StartingReserves();
   foreach(var reserve in reserves)if(!Gameplay.ReconcileNetworkReserve(reserve.Key,reserve.Value))throw new InvalidOperationException("Respawn reserves refused");
   foreach(var profile in Gameplay.OwnedWeaponActionIds){
    int loaded=Networking.R24LanLoadout.Capacity(profile,1);
    string family=Networking.R24LanLoadout.Family(profile);
    int reserve=family==null?0:reserves[family];bool paired=Networking.R24LanLoadout.Paired(profile);
    if(!Gameplay.ReconcileNetworkAmmo(profile,loaded,paired?(loaded+1)/2:-1,paired?loaded/2:-1,reserve))throw new InvalidOperationException("Respawn magazine refused");
   }
   Consumables.ClearCarriedForRespawn();
   if(Explosives!=null)foreach(var item in Explosives.OwnedItems)Explosives.ReconcileNetworkItem(item.Id,false,true);
   Activities.ReconcileNetworkBalance(rules.StartingBuilds);inventoryCapacity=3;RefreshSlotBudget();RefreshLoadout();
  }
